import{_ as a,o as l,c as i,a5 as t}from"./chunks/framework.BPFk9-tb.js";const r="/images/geek-time-ads/Elasticsearch%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98.jpeg",m=JSON.parse('{"title":"Elasticsearch数据建模","description":"","frontmatter":{"date":"2019-12-12T23:46:17","title":"Elasticsearch数据建模"},"headers":[{"level":2,"title":"范式化设计","slug":"范式化设计","link":"#范式化设计","children":[]},{"level":2,"title":"反范式化设计","slug":"反范式化设计","link":"#反范式化设计","children":[]},{"level":2,"title":"对象类型","slug":"对象类型","link":"#对象类型","children":[]},{"level":2,"title":"嵌套对象","slug":"嵌套对象","link":"#嵌套对象","children":[]},{"level":2,"title":"父子关系","slug":"父子关系","link":"#父子关系","children":[]},{"level":2,"title":"应用场景","slug":"应用场景","link":"#应用场景","children":[]},{"level":2,"title":"避免过多字段","slug":"避免过多字段","link":"#避免过多字段","children":[]},{"level":2,"title":"避免正则查询","slug":"避免正则查询","link":"#避免正则查询","children":[]},{"level":2,"title":"避免空值引起的聚合不准","slug":"避免空值引起的聚合不准","link":"#避免空值引起的聚合不准","children":[]},{"level":2,"title":"为索引的Mapping加入Meta信息","slug":"为索引的mapping加入meta信息","link":"#为索引的mapping加入meta信息","children":[]},{"level":2,"title":"重建索引","slug":"重建索引","link":"#重建索引","children":[]},{"level":2,"title":"数据预处理","slug":"数据预处理","link":"#数据预处理","children":[]}],"relativePath":"posts/bigdata/es/olap-2.md","filePath":"posts/bigdata/es/olap-2.md"}'),n={name:"posts/bigdata/es/olap-2.md"};function h(s,e,o,p,c,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h1><p>上一篇<a href="https://l4qiang.me/2018/09/28/es/olap-1/" target="_blank" rel="noreferrer">《基于ElasticSearch的OLAP框架思路》</a>简单介绍了ES的存储结构，本文对ES的数据建模做些整理，是对上文的补充。</p><h1 id="数据建模" tabindex="-1">数据建模 <a class="header-anchor" href="#数据建模" aria-label="Permalink to &quot;数据建模&quot;">​</a></h1><h2 id="范式化设计" tabindex="-1">范式化设计 <a class="header-anchor" href="#范式化设计" aria-label="Permalink to &quot;范式化设计&quot;">​</a></h2><p>在关系型数据库中会强调范式化设计（Normalization），其主要目标是“减少不必要的更新”，但也就带了一个问题“查询缓慢”，因为数据库越范式化，就需要Join越多的表。</p><p>关系型数据库设计时，通常设计时做到3NF，但在必要时进行数据的冗余。以下是范式的简要描述：</p><ul><li>1NF——消除非主属性对键的部分函数依赖</li><li>2NF——消除非主属性对键的传递函数依赖</li><li>3NF——消除主属性对键的传递函数依赖</li><li>BCNF——主属性不依赖主属性</li></ul><h2 id="反范式化设计" tabindex="-1">反范式化设计 <a class="header-anchor" href="#反范式化设计" aria-label="Permalink to &quot;反范式化设计&quot;">​</a></h2><p>范式化的另一个好处呢，就是减少了存储空间（也有可能是早些年存储成本大，才有了范式化设计）。但在存储越来越便宜和数据量越来越大，查询需求也越来越多的情况下，关系型数据库就越来越受到挑战，非关系型数据库不断的涌现出来。其实可以理解来范式化设计与反范式化设计的交锋和解决不同的应用场景问题。</p><p>反范式化设计（Denormalization），就是尽量不去使用关联关系，而是在文档中保存存冗余的数据，将数据扁平化（Flattening）。这样做的优点很明显，就是数据读取性能好，缺点也很明显，不适合在数据频繁修改的场景，一条数据改动，会引起很多数据的更新，对数据一致性提出更高要求。</p><p>ES数据库设计时通常会采用反范式化设计，因为ES并不擅长处理关联关系，一般采用以下四种方法来处理关联：</p><ul><li>对象类型（Object）</li><li>嵌套对象（Nested Object）</li><li>父子关系（Parent/Child）</li><li>应用端关联</li></ul><p>其实应用端关联不属于ES设计的部分，在本文中不再赘述，另外基础的数据类型对数据建模影响不大，需要时参看ES相关文档进行设计即可。</p><h2 id="对象类型" tabindex="-1">对象类型 <a class="header-anchor" href="#对象类型" aria-label="Permalink to &quot;对象类型&quot;">​</a></h2><p>ES采用JSON的文档化存储，而JSON文档天然就是有层级的，文档内可以包含对象（普通对象和数组对象），如果存储数组对象并需要进行查询或统计时，计算结果可能是错误的，这个时候就需要用到嵌套对象。</p><h2 id="嵌套对象" tabindex="-1">嵌套对象 <a class="header-anchor" href="#嵌套对象" aria-label="Permalink to &quot;嵌套对象&quot;">​</a></h2><p>嵌套对象是对象类型的一个特例，允许对象数组中的对象独立索引，Nested文档会被保存在两个Lucene文档中，在查询时做Join处理，因此每次更新，需要重新索引整个对象（包括根对象和嵌套对象）。</p><h2 id="父子关系" tabindex="-1">父子关系 <a class="header-anchor" href="#父子关系" aria-label="Permalink to &quot;父子关系&quot;">​</a></h2><p>ES提供了类似关系型数据库中Join的实现。使用Join数据类型实现，可能过维护Parent/Child的关系，从而分离两个对象。这样呢，父文档和子文档是两个独立的文档，更新父文档时无需重新索引子文档，子文档被添加，更新或者删除时也不会影响父文档和其他的子文档。需要额外的内存维护，读取性能相对差。</p><h1 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h1><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li>对象类型，优先考虑。</li><li>嵌套对象，当数据包含多数值对象，同时有查询需求</li><li>父子关系，当关联文档更新非常频繁时。</li></ul><h2 id="避免过多字段" tabindex="-1">避免过多字段 <a class="header-anchor" href="#避免过多字段" aria-label="Permalink to &quot;避免过多字段&quot;">​</a></h2><ul><li>过多字段不容易维护，Mapping保存在Cluster State中，数据量过大时会对集群性能造成影响。删除或修改需要reindex。</li><li>默认1000，可通过index.mapping.total_fields.limit来进行设置</li><li>Dynamic默认是打开的，只要有新的字段进入Mapping就会更新，导致文档膨胀，可能通过设置Stick，采用Nested Object和Key Value来解决这个问题。</li></ul><h2 id="避免正则查询" tabindex="-1">避免正则查询 <a class="header-anchor" href="#避免正则查询" aria-label="Permalink to &quot;避免正则查询&quot;">​</a></h2><ul><li>正则，通配符查询，特别是前缀查询，性能不好。可以采用Netest字段方式将一个字段拆分成多个字段。</li></ul><h2 id="避免空值引起的聚合不准" tabindex="-1">避免空值引起的聚合不准 <a class="header-anchor" href="#避免空值引起的聚合不准" aria-label="Permalink to &quot;避免空值引起的聚合不准&quot;">​</a></h2><p>null值无论是在关系型数据库，还是在非关系型数据库，都是被特殊对待的。在ES中可以通过设置null_value，来指定字段为null时的默认值。</p><h2 id="为索引的mapping加入meta信息" tabindex="-1">为索引的Mapping加入Meta信息 <a class="header-anchor" href="#为索引的mapping加入meta信息" aria-label="Permalink to &quot;为索引的Mapping加入Meta信息&quot;">​</a></h2><p>Mappings设置无论从功能，还是性能方面来说都非常的重要，Mappings的每一次变更的都可能造成功能和性能的变化或者数据迁移，因此需要增加Meta（版本）信息并利用版本化控制工具（如Git）进行管理。</p><h2 id="重建索引" tabindex="-1">重建索引 <a class="header-anchor" href="#重建索引" aria-label="Permalink to &quot;重建索引&quot;">​</a></h2><p>可以通过update_by_query来对历史数据的新增字段进行索引的重建。因为ES不允许对已有字段修改数据类型，只能通过reindex的方式将一个索引重新索引到一个新的索引上，但可能通过指定别名的方法来使得减少应用程序的修改。</p><h2 id="数据预处理" tabindex="-1">数据预处理 <a class="header-anchor" href="#数据预处理" aria-label="Permalink to &quot;数据预处理&quot;">​</a></h2><p>对于OLAP来说，数据的清洗和转换是不可避免的，而通过Ingest Node和Painless Script。相当于关系型数据库的存储过程或函数。</p><p>Ingest Node：Pipeline&amp;Processor（可实现插件）。</p><p>Painless Script：默认缓存100个。</p><h1 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h1><p><a href="https://www.elastic.co/guide/en/elasticsearch/reference/current/mapping.html" target="_blank" rel="noreferrer">https://www.elastic.co/guide/en/elasticsearch/reference/current/mapping.html</a></p><p>《Elasticsearch核心技术与实战》</p><p><img src="'+r+'" alt=""></p>',40)])])}const g=a(n,[["render",h]]);export{m as __pageData,g as default};
